use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    let mut current = input.as_array().unwrap_or_default();
    let mut previous = current[0].as_i64().unwrap_or_default();

    for &value in current.iter() {
        let next = value.as_i64().unwrap_or_default();
        result.push(next - previous);
        previous = next;
    }

    serde_json::Value::from(result)
}
